float volts;
float resistance;
float kelvin;

if (!g_ready)
  {
    return NAN;
  }

code = adc_read_average(FIREYEYE_ADC_CH_TEMPERATURE);
if (code < 0)
  {
    return NAN;
  }

volts = adc_code_to_volts(code);

/* 分压中点电压为 0 或接近 VREF，说明 NTC 短路/开路 */

if (volts <= 0.02f || volts >= (FIREYEYE_ADC_VREF_VOLTS - 0.02f))

  {
    raw_bus = g_last_bus;
    g_bus_valid = false;
  }
else
  {
    g_last_bus = raw_bus;
    g_bus_valid = true;
  }

/* 关键传感器连续失效时不能继续信任旧读数，直接进入安全侧。 */

sensors_invalid = !g_current_valid || !g_temp_valid || !g_bus_valid;
if (sensors_invalid)
  {
    if (sensor_invalid_tick < DEBOUNCE_COUNT)
      {
        sensor_invalid_tick++;
      }
  }

